+import {ChangeDetectionStrategy, Component, input, model} from '@angular/core';
+import {DecimalPipe} from '@angular/common';
+import {MatCheckbox} from '@angular/material/checkbox';
+
+import {ProfilerFrame} from '../../../../../../../protocol';
